
/* organizacion/app1.js */
const SUPABASE_URL='https://oeodnnomgiddkblnlzay.supabase.co';
const SUPABASE_KEY='sb_publishable_X06jWDKqV6jgKbaa1PrrbQ_zto1XeTJ';
const sb=supabase.createClient(SUPABASE_URL,SUPABASE_KEY,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}});

const ROLE_OPTIONS=['Pastor/a','Colaborador','Líder','Timoteo'];
const MODULES=['organizacion','campamento','efe','lista-sabados','glosario','buffet'];
const SERVICE_AREAS=['Bienvenida','Dinámica','Ofrenda','Ministración','Palabra','Multimedia','Fotografía','Video','Diseño','Recepción','Intercesión','Sonido','Limpieza','Merch','Decoración','Buffet','Organización'];
const NAV=[
  ['my','⌂','Mi TNT'],['schedule','◷','Cronograma'],['saturdays','🗓','Sábados'],['events','◇','Eventos'],
  ['tasks','✓','Mis tareas'],['team','◉','Equipo'],['templates','▦','Plantillas']
];
const STATUS_LABEL={unread:'Todavía no leído',preparing:'En preparación',progress:'Avanzando',review:'Necesita revisión',ready:'Listo',completed:'Terminado',replacement:'Necesita reemplazo'};
const ASSIGN_LABEL={assigned:'Pendiente',read:'Leído',accepted:'Aceptado',declined:'No puedo'};
const RUN_LABEL={pending:'Pendiente',live:'En curso',done:'Terminada'};

const S={session:null,account:null,person:null,view:'my',cronTab:'schedule',selectedEvent:null,selectedDay:null,satMonth:new Date(new Date().getFullYear(),new Date().getMonth(),1),
  people:[],accounts:[],events:[],eventMembers:[],tasks:[],assignees:[],templates:[],templateItems:[],days:[],items:[],responsibles:[],groups:[],groupMembers:[],groupConfigs:[],notifications:[],availability:[],workload:[],moduleAccess:[]};

const $=(s,r=document)=>r.querySelector(s); const $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=(v='')=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const gid=()=>crypto.randomUUID?crypto.randomUUID():Math.random().toString(36).slice(2)+Date.now().toString(36);
const today=()=>new Date().toISOString().slice(0,10);
const fmtDate=d=>d?new Intl.DateTimeFormat('es-AR',{weekday:'short',day:'numeric',month:'short',year:'numeric'}).format(new Date(d+'T12:00:00')):'';
const fmtShort=d=>d?new Intl.DateTimeFormat('es-AR',{day:'2-digit',month:'short'}).format(new Date(d+'T12:00:00')):'';
const fmtTime=t=>t?String(t).slice(0,5):'—';
const age=(birthday,at=new Date())=>{if(!birthday)return null;let b=new Date(birthday+'T12:00:00'),n=at.getFullYear()-b.getFullYear();let m=at.getMonth()-b.getMonth();if(m<0||(m===0&&at.getDate()<b.getDate()))n--;return n};
const toast=(m)=>{let t=$('#toast');t.textContent=m;t.classList.add('show');clearTimeout(toast._t);toast._t=setTimeout(()=>t.classList.remove('show'),2600)};
const errMsg=e=>e?.message||String(e||'Error');
const pBy=id=>S.people.find(p=>p.id===id); const aByPid=id=>S.accounts.find(a=>a.person_id===id);
const displayName=id=>{let p=pBy(id),a=aByPid(id);return a?.nickname||p?.full_name||'Persona'};
const avatarHtml=id=>{let p=pBy(id),a=aByPid(id),name=displayName(id),url=a?.avatar_url;return `<div class="avatar">${url?`<img src="${esc(url)}" alt="">`:esc(name.slice(0,2).toUpperCase())}</div>`};
const currentPersonId=()=>S.person?.id||null;
const isAdmin=()=>S.account?.system_role==='admin'; const isPastor=()=>S.account?.ministry_role==='Pastor/a';
const canManageEvent=id=>isAdmin()||isPastor()||S.eventMembers.some(m=>m.event_id===id&&m.person_id===currentPersonId()&&m.event_role==='organizer');
const canManageTemplates=()=>isAdmin()||isPastor();
const eventBy=id=>S.events.find(e=>e.id===id); const dayBy=id=>S.days.find(d=>d.id===id); const taskBy=id=>S.tasks.find(t=>t.id===id);
const eventMembers=id=>S.eventMembers.filter(m=>m.event_id===id);
const eventTasks=id=>S.tasks.filter(t=>t.event_id===id&&!t.parent_task_id).sort((a,b)=>a.sort_order-b.sort_order);
const childrenOf=id=>S.tasks.filter(t=>t.parent_task_id===id).sort((a,b)=>a.sort_order-b.sort_order);
const eventDays=id=>S.days.filter(d=>d.event_id===id).sort((a,b)=>a.sort_order-b.sort_order);
const dayItems=id=>S.items.filter(i=>i.day_id===id).sort((a,b)=>a.sort_order-b.sort_order);
const itemPeople=id=>S.responsibles.filter(r=>r.item_id===id).map(r=>r.person_id);
const taskPeople=id=>S.assignees.filter(a=>a.task_id===id).map(a=>a.person_id);
const myAssignment=t=>S.assignees.find(a=>a.task_id===t.id&&a.person_id===currentPersonId());
const statusChip=(s)=>`<span class="status ${esc(s)}">${esc(STATUS_LABEL[s]||s)}</span>`;
const assignChip=(s)=>`<span class="status ${esc(s)}">${esc(ASSIGN_LABEL[s]||s)}</span>`;
const runChip=(s)=>`<span class="chip run ${esc(s)}">${esc(RUN_LABEL[s]||s)}</span>`;

function loading(){document.getElementById('app').innerHTML='<div class="skeleton"><div><div class="spinner"></div>Cargando TNT Organización…</div></div>'}
function modal(html,wide=false){document.getElementById('modal').innerHTML=`<div class="modal" data-overlay><section class="sheet ${wide?'wide':''}">${html}</section></div>`;$$('[data-close]').forEach(x=>x.onclick=closeModal);$('[data-overlay]')?.addEventListener('click',e=>{if(e.target.dataset.overlay!==undefined)closeModal()})}
function closeModal(){document.getElementById('modal').innerHTML=''}
function sheetHead(title,sub=''){return `<div class="sheetHead"><div><h2>${esc(title)}</h2>${sub?`<p>${esc(sub)}</p>`:''}</div><button class="close" data-close>×</button></div>`}
function empty(title,text,button='',action=''){return `<div class="empty"><b>${esc(title)}</b>${text?`<div>${esc(text)}</div>`:''}${button?`<div style="margin-top:14px"><button class="btn primary" data-action="${esc(action)}">${esc(button)}</button></div>`:''}</div>`}

async function signInGoogle(){
  const {error}=await sb.auth.signInWithOAuth({provider:'google',options:{redirectTo:location.origin+'/organizacion/'}}); if(error)toast('Google todavía no está habilitado en Supabase. Podés entrar por email mientras tanto.');
}
async function magicLink(){let email=$('#loginEmail')?.value.trim();if(!email)return toast('Escribí tu email');let {error}=await sb.auth.signInWithOtp({email,options:{emailRedirectTo:location.origin+'/organizacion/'}});toast(error?errMsg(error):'Te enviamos un enlace de ingreso')}
function renderLogin(){document.getElementById('app').innerHTML=`<main class="login"><section class="loginCard"><div class="loginLogo">T</div><h1>TNT Organización</h1><p>Equipos, eventos, responsabilidades y ejecución del ministerio en un solo lugar.</p><button class="google" id="googleLogin">Continuar con Google</button><div class="divider">o por email</div><input id="loginEmail" type="email" placeholder="tu@email.com"><button class="btn" id="magicLogin">Enviar enlace de acceso</button><p class="tiny" style="margin-top:16px">El Admin inicial se asigna de forma segura por email. Después puede otorgar Admin a otras personas desde la aplicación.</p></section></main>`;$('#googleLogin').onclick=signInGoogle;$('#magicLogin').onclick=magicLink}

async function boot(){loading();let {data:{session}}=await sb.auth.getSession();S.session=session;if(!session){renderLogin();return}await initAuthed()}
sb.auth.onAuthStateChange((event,session)=>{if(event==='SIGNED_OUT'){S.session=null;S.account=null;S.person=null;renderLogin()}else if(session&&!S.session){S.session=session;setTimeout(initAuthed,0)}});

async function initAuthed(){loading();try{
  const ensured=await sb.rpc('tnt_ensure_account');
  if(ensured.error)throw ensured.error;
  for(let n=0;n<5;n++){
    let {data,error}=await sb.from('tnt_accounts').select('*').eq('auth_user_id',S.session.user.id).maybeSingle();if(error)throw error;if(data){S.account=data;break}await new Promise(r=>setTimeout(r,350));
  }
  if(!S.account)throw new Error('No se pudo crear o vincular tu perfil TNT.');
  let {data:p,error:pe}=await sb.from('tnt_people').select('*').eq('id',S.account.person_id).single();if(pe)throw pe;S.person=p;
  await Promise.allSettled([sb.rpc('tnt_touch_last_seen'),sb.rpc('tnt_generate_personal_reminders')]);
  await loadAll();readDeepLink();render();
}catch(e){document.getElementById('app').innerHTML=`<div class="login"><div class="loginCard"><h1>No pudimos entrar</h1><p>${esc(errMsg(e))}</p><button class="btn" id="retry">Reintentar</button><button class="btn danger" id="logout">Cerrar sesión</button></div></div>`;$('#retry').onclick=initAuthed;$('#logout').onclick=()=>sb.auth.signOut()}}

async function loadAll(){
  const q=[
    ['people',sb.from('tnt_people').select('*').order('full_name')],['accounts',sb.from('tnt_accounts').select('*')],['events',sb.from('tnt_events').select('*').order('start_date')],
    ['eventMembers',sb.from('tnt_event_members').select('*')],['tasks',sb.from('tnt_tasks').select('*').order('sort_order')],['assignees',sb.from('tnt_task_assignees').select('*')],
    ['templates',sb.from('tnt_templates').select('*').order('name')],['templateItems',sb.from('tnt_template_items').select('*').order('sort_order')],
    ['days',sb.from('tnt_schedule_days').select('*').order('sort_order')],['items',sb.from('tnt_schedule_items').select('*').order('sort_order')],['responsibles',sb.from('tnt_schedule_responsibles').select('*')],
    ['groups',sb.from('tnt_groups').select('*').order('sort_order')],['groupMembers',sb.from('tnt_group_members').select('*')],['groupConfigs',sb.from('tnt_group_configs').select('*')],
    ['notifications',sb.from('tnt_notifications').select('*').order('created_at',{ascending:false}).limit(200)],['availability',sb.from('tnt_availability').select('*')],
    ['workload',sb.from('tnt_monthly_workload').select('*')],['moduleAccess',sb.from('tnt_module_access').select('*')]
  ];
  const res=await Promise.all(q.map(x=>x[1]));res.forEach((r,i)=>{if(r.error)console.warn(q[i][0],r.error);else S[q[i][0]]=r.data||[]});
  S.account=S.accounts.find(a=>a.person_id===S.account.person_id)||S.account;S.person=S.people.find(p=>p.id===S.account.person_id)||S.person;
  if(!S.selectedEvent){let future=S.events.find(e=>e.end_date>=today());S.selectedEvent=(future||S.events[0])?.id||null}if(S.selectedEvent&&!S.selectedDay)S.selectedDay=eventDays(S.selectedEvent)[0]?.id||null;
}
function readDeepLink(){let p=new URLSearchParams(location.search);if(p.get('task')){S.view='tasks';setTimeout(()=>taskDetailModal(p.get('task')),100)}if(p.get('event')){S.view='events';S.selectedEvent=p.get('event')}}

function navButtons(mobile=false){let arr=[...NAV];if(isAdmin())arr.push(['admin','⚙','Admin']);return arr.map(([id,ico,label])=>`<button class="navBtn ${S.view===id?'on':''} ${id==='admin'?'admin':''}" data-view="${id}"><span class="ni">${ico}</span><span>${label}</span></button>`).join('')}
function shell(content,title,sub=''){let unread=S.notifications.filter(n=>!n.read_at&&(n.person_id===currentPersonId()||n.person_id===null)).length;return `<div class="appShell"><aside class="sidebar"><div class="brand"><div class="brandMark">T</div><div><b>TNT Organización</b><small>Trastornadores</small></div></div><div class="navList">${navButtons()}</div><div class="sideFoot"><button class="userMini" data-action="profile">${avatarHtml(currentPersonId())}<div><b>${esc(S.account.nickname||S.person.full_name)}</b><small>${esc(S.account.system_role==='admin'?'Admin · '+S.account.ministry_role:S.account.ministry_role)}</small></div></button><button class="signout" data-action="signout">Cerrar sesión</button></div></aside><main class="main"><header class="topbar"><div class="topTitle"><b>${esc(title)}</b><small>${esc(sub)}</small></div><div class="sp"></div><button class="iconBtn" data-action="notifications">🔔${unread?`<span class="badgeDot">${unread>9?'9+':unread}</span>`:''}</button><button class="pillBtn" data-action="profile">${esc(S.account.nickname||S.person.full_name)}</button></header>${content}</main><nav class="mobileNav">${navButtons(true)}</nav></div>`}
function render(){let out,title,sub;switch(S.view){case'my':[out,title,sub]=[viewMy(),'Mi TNT','Tu panel personal'];break;case'schedule':[out,title,sub]=[viewSchedule(),'Cronograma','Horarios, responsables y grupos'];break;case'saturdays':[out,title,sub]=[viewSaturdays(),'Sábados','Reuniones normales de TNT'];break;case'events':[out,title,sub]=[viewEvents(),'Eventos','Congresos, campamentos y actividades especiales'];break;case'tasks':[out,title,sub]=[viewMyTasks(),'Mis tareas','Asignaciones y seguimiento'];break;case'team':[out,title,sub]=[viewTeam(),'Equipo','Perfiles, disponibilidad y carga'];break;case'templates':[out,title,sub]=[viewTemplates(),'Plantillas','Estructuras reutilizables'];break;case'admin':[out,title,sub]=[viewAdmin(),'Administración','Usuarios, roles y accesos'];break;default:S.view='my';return render()}document.getElementById('app').innerHTML=shell(out,title,sub);bindGlobal()}
function bindGlobal(){
  $$('[data-view]').forEach(b=>b.onclick=()=>{S.view=b.dataset.view;render()});
  $$('[data-action]').forEach(b=>b.onclick=()=>handleAction(b.dataset.action,b));
  $$('[data-event-open]').forEach(b=>b.onclick=()=>eventDetailModal(b.dataset.eventOpen));
  $$('[data-task-open]').forEach(b=>b.onclick=()=>taskDetailModal(b.dataset.taskOpen));
  $$('[data-person-open]').forEach(b=>b.onclick=()=>personResponsibilitiesModal(b.dataset.personOpen));
}
async function handleAction(a,b){
  if(a==='signout')return sb.auth.signOut();if(a==='profile')return profileModal(currentPersonId());if(a==='notifications')return notificationsModal();
  if(a==='new-saturday')return saturdayCreateModal();if(a==='new-event')return eventCreateModal();if(a==='new-person')return profileModal(null,true);
  if(a==='new-template')return templateModal();if(a==='general-notification')return generalNotificationModal();
  if(a==='group-config')return groupConfigModal(S.selectedDay);if(a==='event-members')return eventMembersModal(S.selectedEvent);
}


/* organizacion/app2.js */
function viewMy(){
  let myA=S.assignees.filter(a=>a.person_id===currentPersonId()&&a.assignment_status!=='declined').map(a=>({a,t:taskBy(a.task_id)})).filter(x=>x.t).sort((x,y)=>(x.t.due_at||'9999').localeCompare(y.t.due_at||'9999'));
  let upcoming=S.events.filter(e=>e.end_date>=today()).slice(0,5),notes=S.notifications.filter(n=>n.person_id===currentPersonId()||n.person_id===null).slice(0,5);
  let open=myA.filter(x=>x.t.status!=='completed').length;return `<div class="page"><section class="hero"><div class="eyebrow">Tu espacio</div><h1>Hola, ${esc(S.account.nickname||S.person.full_name)} 👋</h1><p>Todo lo que necesitás servir, confirmar y organizar sin perseguir mensajes por WhatsApp.</p></section><div class="grid g4"><div class="card kpi"><b>${open}</b><span>Tareas abiertas</span></div><div class="card kpi"><b>${notes.filter(n=>!n.read_at).length}</b><span>Notificaciones</span></div><div class="card kpi"><b>${upcoming.length}</b><span>Próximos eventos</span></div><div class="card kpi"><b>${workloadFor(currentPersonId())}</b><span>Asignaciones este mes</span></div></div><div class="sectionHead"><h2>Próximo</h2><button class="btn small" data-view="tasks">Ver todas</button></div>${myA.length?`<div class="list">${myA.slice(0,5).map(({a,t})=>taskRow(t,a)).join('')}</div>`:empty('Sin asignaciones','Cuando te asignen algo va a aparecer acá.')}<div class="sectionHead"><h2>Próximos eventos</h2><button class="btn small" data-view="events">Ver eventos</button></div>${upcoming.length?`<div class="grid g2">${upcoming.map(eventCard).join('')}</div>`:empty('No hay eventos próximos','')}<div class="sectionHead"><h2>Notificaciones</h2></div>${notes.length?`<div class="list">${notes.map(noteRow).join('')}</div>`:empty('Sin notificaciones','')}</div>`}
function taskRow(t,a){let e=eventBy(t.event_id);return `<button class="rowCard" data-task-open="${t.id}"><div class="ico">${esc(t.icon||'✓')}</div><div><b>${esc(t.title)}</b><div class="meta">${esc(e?.name||'Evento')} ${t.due_at?'· vence '+new Date(t.due_at).toLocaleDateString('es-AR'):''}</div><div class="chips">${statusChip(t.status)}${a?assignChip(a.assignment_status):''}</div></div><span class="arr">›</span></button>`}
function noteRow(n){return `<div class="rowCard"><div class="ico">🔔</div><div><b>${esc(n.title)}</b><div class="meta">${esc(n.body||'')}</div><div class="tiny">${new Date(n.created_at).toLocaleString('es-AR')}</div></div>${n.href?`<button class="btn small" data-note-href="${esc(n.href)}">Abrir</button>`:''}</div>`}
function eventCard(e){return `<button class="card click" data-event-open="${e.id}"><div class="quick"><div class="ico">${e.kind==='saturday'?'🗓':e.kind==='camp'?'🏕️':'◇'}</div><div class="grow"><h3>${esc(e.name)}</h3><p>${fmtDate(e.start_date)}${e.end_date!==e.start_date?' → '+fmtDate(e.end_date):''}${e.location?' · '+esc(e.location):''}</p><div class="chips"><span class="chip">${esc(e.status)}</span>${e.event_mode?'<span class="chip">▶ Modo evento</span>':''}</div></div><span class="arr">›</span></div></button>`}
function workloadFor(pid){let now=new Date(),m=`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-01`;return S.workload.find(x=>x.person_id===pid&&x.month===m)?.assignments||0}

function viewSchedule(){
  let ev=S.events.filter(e=>e.end_date>=new Date(Date.now()-86400000*30).toISOString().slice(0,10));if(!S.selectedEvent&&ev[0])S.selectedEvent=ev[0].id;let e=eventBy(S.selectedEvent);if(!e)return `<div class="page">${empty('Todavía no hay eventos','Creá un sábado o evento para empezar.',isPastor()||isAdmin()?'Crear evento':'','new-event')}</div>`;
  let days=eventDays(e.id);if(!S.selectedDay||!days.some(d=>d.id===S.selectedDay))S.selectedDay=days[0]?.id||null;
  return `<div class="page"><div class="selectBar"><select id="eventSelect" class="control">${S.events.map(x=>`<option value="${x.id}" ${x.id===e.id?'selected':''}>${esc(x.name)} · ${fmtShort(x.start_date)}</option>`).join('')}</select><div class="actions">${canManageEvent(e.id)?`<button class="btn ${e.event_mode?'good':''}" id="toggleEventMode">${e.event_mode?'■ Salir modo evento':'▶ Modo evento'}</button><button class="btn" data-action="event-members">Personas</button>`:''}</div></div><div class="tabs"><button class="tab ${S.cronTab==='schedule'?'on':''}" data-cron="schedule">Cronograma</button><button class="tab ${S.cronTab==='groups'?'on':''}" data-cron="groups">Grupos por día</button></div>${S.cronTab==='schedule'?schedulePanel(e,days):groupsPanel(e,days)}</div>`}
function schedulePanel(e,days){return `<div class="sectionHead"><h2>${esc(e.name)}</h2>${canManageEvent(e.id)?'<button class="btn primary small" id="addDay">+ Día</button>':''}</div>${days.length?`<div class="tabs">${days.map(d=>`<button class="tab ${d.id===S.selectedDay?'on':''}" data-day="${d.id}">${esc(d.label)}${d.date?' · '+fmtShort(d.date):''}</button>`).join('')}</div>${scheduleDayPanel(e,dayBy(S.selectedDay))}`:empty('Sin días cargados','Agregá “Día 1 / Viernes”, “Día 2 / Sábado”, etc.',canManageEvent(e.id)?'Agregar primer día':'','')}`}
function scheduleDayPanel(e,d){if(!d)return'';let its=dayItems(d.id);return `<div class="sectionHead"><h2>${esc(d.label)}</h2>${canManageEvent(e.id)?'<button class="btn primary small" id="addScheduleItem">+ Actividad</button>':''}</div>${its.length?`<div class="timeline">${its.map(i=>scheduleItemRow(e,i)).join('')}</div>`:empty('Sin actividades','Cargá juegos, comidas, reuniones y todo el cronograma.')}`}
function scheduleItemRow(e,i){let rp=itemPeople(i.id);return `<article class="timeItem"><div class="timeBox">${fmtTime(i.starts_at)}<small>${i.duration_minutes?i.duration_minutes+' min':''}</small></div><div><h3 style="margin:0">${esc(i.title)}</h3><div class="tiny">${esc(i.item_type)}${i.location?' · '+esc(i.location):''}</div>${rp.length?`<div class="responsibles">${rp.map(id=>`<button class="personLink" data-person-open="${id}">${esc(displayName(id))}</button>`).join('')}</div>`:'<div class="tiny" style="margin-top:7px">Sin responsable</div>'}</div><div class="actions">${runChip(i.run_status||'pending')}<button class="btn small" data-item-open="${i.id}">Ver</button>${e.event_mode&&canManageEvent(e.id)?`<button class="btn small" data-run-next="${i.id}">Cambiar estado</button>`:''}</div></article>`}

function groupsPanel(e,days){if(!days.length)return empty('Primero cargá los días','Los equipos se generan por día.');let d=dayBy(S.selectedDay)||days[0];let gs=S.groups.filter(g=>g.event_id===e.id&&g.day_id===d.id).sort((a,b)=>a.sort_order-b.sort_order);let members=eventMembers(e.id).filter(m=>m.include_in_groups!==false);let missing=[];let cfg=S.groupConfigs.find(c=>c.event_id===e.id&&c.day_id===d.id);for(let m of members){let p=pBy(m.person_id);if(!p)continue;if((cfg?.balance_sex??true)&&(!p.sex||p.sex==='U'))missing.push(displayName(p.id)+' · sexo');if((cfg?.balance_age??true)&&!p.birthday)missing.push(displayName(p.id)+' · nacimiento')}
  return `<div class="tabs">${days.map(x=>`<button class="tab ${x.id===d.id?'on':''}" data-day="${x.id}">${esc(x.label)}</button>`).join('')}</div><div class="sectionHead"><div><h2>División · ${esc(d.label)}</h2><div class="tiny">${members.length} personas incluidas</div></div>${canManageEvent(e.id)?'<div class="actions"><button class="btn" data-action="event-members">Participantes</button><button class="btn primary" data-action="group-config">Generar / configurar</button></div>':''}</div>${missing.length?`<div class="warning">Para equilibrar correctamente faltan datos confirmados: ${esc([...new Set(missing)].join(', '))}. La app no infiere sexo por el nombre.</div>`:''}${gs.length?`<div class="groupGrid" style="margin-top:13px">${gs.map(g=>groupBox(g,gs)).join('')}</div>`:empty('Todavía no hay equipos','Configurá Rojo/Azul (o los nombres que quieras) y generá la división.')}`}
function groupBox(g,allGroups){let ms=S.groupMembers.filter(m=>m.group_id===g.id);let avg=ms.length?Math.round(ms.reduce((s,m)=>s+(m.age_snapshot||0),0)/ms.length):0;let sex=ms.reduce((o,m)=>(o[m.sex_snapshot||'U']=(o[m.sex_snapshot||'U']||0)+1,o),{});return `<section class="teamBox"><header class="teamHead"><h3><span class="teamDot" style="background:${esc(g.color)}"></span>${esc(g.name)}</h3><span class="tiny">${ms.length} · edad prom. ${avg||'—'} · F ${sex.F||0} / M ${sex.M||0}</span></header><div class="teamMembers">${ms.map(m=>{let p=pBy(m.person_id);return `<div class="member">${avatarHtml(m.person_id)}<div><b>${esc(displayName(m.person_id))}</b><div class="tiny">${m.age_snapshot??'—'} años · ${m.sex_snapshot==='F'?'F':m.sex_snapshot==='M'?'M':'Sin confirmar'}</div></div>${canManageEvent(g.event_id)?`<select data-move-person="${m.person_id}" data-from-group="${g.id}">${allGroups.map(x=>`<option value="${x.id}" ${x.id===g.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select>`:''}</div>`}).join('')||'<div class="tiny">Sin personas</div>'}</div></section>`}

function viewSaturdays(){let m=S.satMonth,year=m.getFullYear(),month=m.getMonth();let dates=[];let x=new Date(year,month,1);while(x.getMonth()===month){if(x.getDay()===6)dates.push(x.toISOString().slice(0,10));x.setDate(x.getDate()+1)}let monthLabel=new Intl.DateTimeFormat('es-AR',{month:'long',year:'numeric'}).format(m);return `<div class="page"><div class="sectionHead"><div><h2 style="text-transform:capitalize">${esc(monthLabel)}</h2><div class="tiny">Los sábados aparecen automáticamente</div></div><div class="actions"><button class="btn" id="satPrev">‹</button><button class="btn" id="satNext">›</button>${isAdmin()||isPastor()?'<button class="btn primary" data-action="new-saturday">+ Sábado</button>':''}</div></div><div class="grid g2">${dates.map(d=>{let e=S.events.find(e=>e.kind==='saturday'&&e.start_date===d);return e?eventCard(e):`<div class="card"><div class="quick"><div class="ico">🗓</div><div class="grow"><h3>${fmtDate(d)}</h3><p>Sin preparar</p></div>${isAdmin()||isPastor()?`<button class="btn small primary" data-create-sat="${d}">Preparar</button>`:''}</div></div>`}).join('')}</div></div>`}
function viewEvents(){let es=S.events.filter(e=>e.kind!=='saturday');return `<div class="page"><section class="hero"><div class="eyebrow">Organización general</div><h1>Eventos</h1><p>Congresos, campamentos, vigilias, salidas y actividades especiales con responsables, tareas y seguimiento.</p></section><div class="sectionHead"><h2>Todos</h2>${isAdmin()||isPastor()?'<button class="btn primary" data-action="new-event">+ Crear evento</button>':''}</div>${es.length?`<div class="grid g2">${es.map(eventCard).join('')}</div>`:empty('Sin eventos','Creá uno desde una plantilla.')}</div>`}
function viewMyTasks(){let xs=S.assignees.filter(a=>a.person_id===currentPersonId()).map(a=>({a,t:taskBy(a.task_id)})).filter(x=>x.t).sort((x,y)=>(x.t.due_at||'9999').localeCompare(y.t.due_at||'9999'));return `<div class="page"><section class="hero"><div class="eyebrow">Responsabilidades</div><h1>Mis tareas</h1><p>Leé, aceptá o avisá si no podés. El estado de la tarea se gestiona por separado.</p></section>${xs.length?`<div class="list">${xs.map(({a,t})=>taskRow(t,a)).join('')}</div>`:empty('Sin tareas','')}</div>`}
function viewTeam(){let q=(window._teamSearch||'').toLowerCase();let ps=S.people.filter(p=>p.active!==false&&displayName(p.id).toLowerCase().includes(q));return `<div class="page"><div class="sectionHead"><div><h2>Equipo TNT</h2><div class="tiny">${ps.length} perfiles</div></div><div class="actions"><input class="control" id="teamSearch" placeholder="Buscar" value="${esc(window._teamSearch||'')}">${isAdmin()?'<button class="btn primary" data-action="new-person">+ Perfil</button>':''}</div></div><div class="peopleGrid">${ps.map(personCard).join('')}</div></div>`}
function personCard(p){let a=aByPid(p.id),w=workloadFor(p.id),pct=Math.min(100,w*18);return `<article class="personCard"><div class="personTop">${avatarHtml(p.id)}<div class="grow"><h3>${esc(a?.nickname||p.full_name)}</h3><p>${esc(a?.ministry_role||'Sin rol')}${a?.system_role==='admin'?' · Admin':''}</p></div><button class="btn small" data-person-open="${p.id}">Ver</button></div><div class="workload"><div class="bar"><span style="width:${pct}%"></span></div><span class="tiny">${w} este mes</span></div>${a?.service_areas?.length?`<div class="chips">${a.service_areas.slice(0,3).map(x=>`<span class="chip">${esc(x)}</span>`).join('')}</div>`:''}</article>`}
function viewTemplates(){return `<div class="page"><section class="hero"><div class="eyebrow">Reutilizable</div><h1>Plantillas</h1><p>Creá un sábado, evento evangelístico o congreso con su estructura ya preparada.</p></section><div class="sectionHead"><h2>Plantillas</h2>${canManageTemplates()?'<button class="btn primary" data-action="new-template">+ Plantilla</button>':''}</div><div class="grid g2">${S.templates.map(t=>templateCard(t)).join('')}</div></div>`}
function templateCard(t){let items=S.templateItems.filter(i=>i.template_id===t.id).sort((a,b)=>a.sort_order-b.sort_order);return `<article class="card"><div class="quick"><div class="ico">${t.kind==='saturday'?'🗓':'▦'}</div><div class="grow"><h3>${esc(t.name)}</h3><p>${esc(t.description||'')}</p></div>${t.is_default?'<span class="chip">Predeterminada</span>':''}</div><div class="chips">${items.map(i=>`<span class="chip">${esc(i.icon||'✓')} ${esc(i.title)}</span>`).join('')}</div>${canManageTemplates()?`<div class="actions" style="margin-top:13px"><button class="btn small" data-template-edit="${t.id}">Editar</button><button class="btn small primary" data-template-start="${t.id}">Usar</button></div>`:''}</article>`}
function viewAdmin(){if(!isAdmin())return `<div class="page">${empty('Solo Admin','No tenés permiso para esta sección.')}</div>`;let accounts=S.accounts.map(a=>({a,p:pBy(a.person_id)})).filter(x=>x.p);return `<div class="page"><section class="hero"><div class="eyebrow">Sistema</div><h1>Administración</h1><p>Gestioná roles TNT, administradores, acceso a módulos y cuentas habilitadas.</p></section><div class="sectionHead"><h2>Usuarios</h2><div class="actions"><button class="btn" data-action="general-notification">Notificación general</button><button class="btn primary" data-action="new-person">+ Perfil / invitación</button></div></div><div class="list">${accounts.map(({a,p})=>adminUserRow(a,p)).join('')}</div></div>`}
function adminUserRow(a,p){return `<div class="rowCard">${avatarHtml(p.id)}<div><b>${esc(a.nickname||p.full_name)}</b><div class="meta">${esc(a.email||'Sin email')} · ${a.auth_user_id?'Cuenta vinculada':'Pendiente de ingreso'}</div><div class="chips"><span class="chip">${esc(a.ministry_role)}</span>${a.system_role==='admin'?'<span class="chip">Admin</span>':''}${!a.enabled?'<span class="status declined">Deshabilitado</span>':''}</div></div><div class="actions"><button class="btn small" data-admin-user="${p.id}">Gestionar</button></div></div>`}


/* organizacion/org3a.js */
function bindViewSpecific(){
  if(S.view==='schedule')bindSchedule();if(S.view==='saturdays')bindSaturdays();if(S.view==='team'){let x=$('#teamSearch');if(x)x.oninput=e=>{window._teamSearch=e.target.value;render()}}if(S.view==='templates'){$$('[data-template-edit]').forEach(b=>b.onclick=()=>templateModal(b.dataset.templateEdit));$$('[data-template-start]').forEach(b=>b.onclick=()=>eventCreateModal(b.dataset.templateStart))}if(S.view==='admin')$$('[data-admin-user]').forEach(b=>b.onclick=()=>adminUserModal(b.dataset.adminUser));
  $$('[data-note-href]').forEach(b=>b.onclick=()=>openInternal(b.dataset.noteHref));
}
const _render=render;render=function(){_render();bindViewSpecific()}

function bindSchedule(){
  $('#eventSelect')?.addEventListener('change',e=>{S.selectedEvent=e.target.value;S.selectedDay=eventDays(S.selectedEvent)[0]?.id||null;render()});
  $$('[data-cron]').forEach(b=>b.onclick=()=>{S.cronTab=b.dataset.cron;render()});$$('[data-day]').forEach(b=>b.onclick=()=>{S.selectedDay=b.dataset.day;render()});
  $('#toggleEventMode')?.addEventListener('click',async()=>{let e=eventBy(S.selectedEvent);let {error}=await sb.from('tnt_events').update({event_mode:!e.event_mode}).eq('id',e.id);if(error)return toast(errMsg(error));await loadAll();render()});
  $('#addDay')?.addEventListener('click',()=>dayModal());$('#addScheduleItem')?.addEventListener('click',()=>scheduleItemModal());
  $$('[data-item-open]').forEach(b=>b.onclick=()=>scheduleItemDetailModal(b.dataset.itemOpen));
  $$('[data-run-next]').forEach(b=>b.onclick=()=>cycleRunStatus(b.dataset.runNext));
  $$('[data-move-person]').forEach(s=>s.onchange=()=>moveGroupMember(s.dataset.movePerson,s.dataset.fromGroup,s.value));
}
function bindSaturdays(){
  $('#satPrev')?.addEventListener('click',()=>{S.satMonth=new Date(S.satMonth.getFullYear(),S.satMonth.getMonth()-1,1);render()});$('#satNext')?.addEventListener('click',()=>{S.satMonth=new Date(S.satMonth.getFullYear(),S.satMonth.getMonth()+1,1);render()});
  $$('[data-create-sat]').forEach(b=>b.onclick=()=>createSaturday(b.dataset.createSat));
}

async function createSaturday(date){let {data,error}=await sb.rpc('tnt_create_saturday',{p_date:date,p_name:'Sábado TNT'});if(error)return toast(errMsg(error));await loadAll();toast('Sábado preparado');eventDetailModal(data)}
function saturdayCreateModal(){modal(`${sheetHead('Preparar sábado')}<form class="form" id="satForm"><div class="field"><label>Fecha</label><input type="date" name="date" required></div><div class="field"><label>Nombre</label><input name="name" value="Sábado TNT"></div><button class="btn primary">Crear desde plantilla</button></form>`);$('#satForm').onsubmit=async e=>{e.preventDefault();let f=new FormData(e.target),{data,error}=await sb.rpc('tnt_create_saturday',{p_date:f.get('date'),p_name:f.get('name')});if(error)return toast(errMsg(error));closeModal();await loadAll();toast('Sábado creado');eventDetailModal(data)}}
function eventCreateModal(templateId=''){let opts=S.templates.map(t=>`<option value="${t.id}" ${t.id===templateId?'selected':''}>${esc(t.name)}</option>`).join('');modal(`${sheetHead('Crear evento','Usá una plantilla y después modificá lo que necesites.')}<form class="form" id="eventForm"><div class="field"><label>Plantilla</label><select name="template" required>${opts}</select></div><div class="field"><label>Nombre del evento</label><input name="name" required placeholder="Congreso TNT"></div><div class="formRow"><div class="field"><label>Desde</label><input type="date" name="start" required></div><div class="field"><label>Hasta</label><input type="date" name="end"></div></div><div class="field"><label>Lugar</label><input name="location"></div><button class="btn primary">Crear evento</button></form>`);$('#eventForm').onsubmit=async e=>{e.preventDefault();let f=new FormData(e.target),tpl=S.templates.find(t=>t.id===f.get('template'));let {data,error}=await sb.rpc('tnt_create_event_from_template',{p_template:f.get('template'),p_name:f.get('name'),p_start:f.get('start'),p_end:f.get('end')||f.get('start'),p_location:f.get('location')||null,p_kind:tpl?.kind||'event'});if(error)return toast(errMsg(error));closeModal();await loadAll();toast('Evento creado');eventDetailModal(data)}}

function eventDetailModal(id){let e=eventBy(id);if(!e)return;let tasks=eventTasks(id),members=eventMembers(id),orgs=members.filter(m=>m.event_role==='organizer');let manager=canManageEvent(id);modal(`${sheetHead(e.name,`${fmtDate(e.start_date)}${e.end_date!==e.start_date?' → '+fmtDate(e.end_date):''}`)}<div class="grid g3"><div class="card"><h3>Estado</h3><div class="chips"><span class="chip">${esc(e.status)}</span>${e.event_mode?'<span class="chip">▶ Modo evento</span>':''}</div></div><div class="card"><h3>Organizadores</h3><div class="responsibles">${orgs.map(m=>`<button class="personLink" data-person-open="${m.person_id}">${esc(displayName(m.person_id))}</button>`).join('')||'<span class="tiny">Sin organizadores</span>'}</div></div><div class="card"><h3>Participantes</h3><p>${members.filter(m=>m.include_in_groups!==false).length} incluidos para grupos</p></div></div><div class="sectionHead"><h2>Tareas</h2>${manager?`<div class="actions"><button class="btn" id="manageEventMembers">Personas</button><button class="btn primary" id="newTask">+ Tarea</button></div>`:''}</div>${tasks.length?`<div class="list">${tasks.map(t=>taskRow(t,myAssignment(t))).join('')}</div>`:empty('Sin tareas','')}`,true);$$('[data-task-open]').forEach(b=>b.onclick=()=>taskDetailModal(b.dataset.taskOpen));$$('[data-person-open]').forEach(b=>b.onclick=()=>personResponsibilitiesModal(b.dataset.personOpen));$('#manageEventMembers')?.addEventListener('click',()=>eventMembersModal(id));$('#newTask')?.addEventListener('click',()=>taskEditModal(null,id))}

function dayModal(d=null){let e=eventBy(S.selectedEvent),days=eventDays(e.id);modal(`${sheetHead(d?'Editar día':'Agregar día')}<form class="form" id="dayForm"><div class="field"><label>Nombre</label><input name="label" value="${esc(d?.label||`Día ${days.length+1}`)}" placeholder="Día 1 / Viernes" required></div><div class="field"><label>Fecha</label><input type="date" name="date" value="${esc(d?.date||'')}"></div><button class="btn primary">Guardar</button></form>`);$('#dayForm').onsubmit=async ev=>{ev.preventDefault();let f=new FormData(ev.target),payload={event_id:e.id,label:f.get('label'),date:f.get('date')||null,sort_order:d?.sort_order??days.length};let q=d?sb.from('tnt_schedule_days').update(payload).eq('id',d.id):sb.from('tnt_schedule_days').insert(payload).select().single();let {data,error}=await q;if(error)return toast(errMsg(error));closeModal();await loadAll();S.selectedDay=d?.id||data?.id;render()}}


/* organizacion/org3b.js */
function scheduleItemModal(item=null){let d=dayBy(S.selectedDay),e=eventBy(d?.event_id);if(!d||!e)return;let selected=item?itemPeople(item.id):[];let pool=eventMembers(e.id).map(m=>m.person_id);if(!pool.length)pool=S.people.map(p=>p.id);modal(`${sheetHead(item?'Editar actividad':'Nueva actividad',d.label)}<form class="form" id="itemForm"><div class="formRow"><div class="field"><label>Nombre</label><input name="title" value="${esc(item?.title||'')}" required></div><div class="field"><label>Tipo</label><select name="type">${['game','activity','meal','meeting','other'].map(x=>`<option ${item?.item_type===x?'selected':''}>${x}</option>`).join('')}</select></div></div><div class="formRow three"><div class="field"><label>Hora</label><input type="time" name="time" value="${esc(item?.starts_at?.slice(0,5)||'')}"></div><div class="field"><label>Duración (min)</label><input type="number" name="duration" min="0" value="${esc(item?.duration_minutes||'')}"></div><div class="field"><label>Lugar</label><input name="location" value="${esc(item?.location||'')}"></div></div><div class="field"><label>Descripción / instrucciones</label><textarea name="description">${esc(item?.description||'')}</textarea></div><div class="field"><label>Video explicativo (YouTube)</label><input name="video" value="${esc(item?.video_url||'')}" placeholder="https://youtube.com/..."></div><div class="field"><label>Materiales</label><textarea name="materials">${esc(item?.materials||'')}</textarea></div><div class="field"><label>Responsables</label><div class="checkList">${pool.map(id=>`<label class="checkRow"><input type="checkbox" name="person" value="${id}" ${selected.includes(id)?'checked':''}>${avatarHtml(id)}<span>${esc(displayName(id))}</span><small>${esc(aByPid(id)?.ministry_role||'')}</small></label>`).join('')}</div></div><button class="btn primary">Guardar</button></form>`);$('#itemForm').onsubmit=async ev=>{ev.preventDefault();let f=new FormData(ev.target),payload={day_id:d.id,title:f.get('title'),item_type:f.get('type'),starts_at:f.get('time')||null,duration_minutes:Number(f.get('duration'))||null,location:f.get('location')||null,description:f.get('description')||null,video_url:f.get('video')||null,materials:f.get("materials")||null,sort_order:item?.sort_order??dayItems(d.id).length};let id=item?.id;if(item){let {error}=await sb.from('tnt_schedule_items').update(payload).eq('id',id);if(error)return toast(errMsg(error))}else{let {data,error}=await sb.from('tnt_schedule_items').insert(payload).select().single();if(error)return toast(errMsg(error));id=data.id}let ids=f.getAll('person');await sb.from('tnt_schedule_responsibles').delete().eq('item_id',id);if(ids.length){let {error}=await sb.from('tnt_schedule_responsibles').insert(ids.map(person_id=>({item_id:id,person_id})));if(error)return toast(errMsg(error))}closeModal();await loadAll();render()}}
function youtubeEmbed(url){try{let u=new URL(url),id=u.hostname.includes('youtu.be')?u.pathname.slice(1):u.searchParams.get('v');return id?`<iframe style="width:100%;aspect-ratio:16/9;border:0;border-radius:16px" src="https://www.youtube.com/embed/${encodeURIComponent(id)}" allowfullscreen></iframe>`:''}catch{return''}}
function scheduleItemDetailModal(id){let i=S.items.find(x=>x.id===id),d=dayBy(i?.day_id),e=eventBy(d?.event_id);if(!i||!e)return;let rp=itemPeople(i.id);modal(`${sheetHead(i.title,`${d.label} · ${fmtTime(i.starts_at)}${i.duration_minutes?' · '+i.duration_minutes+' min':''}`)}${i.video_url?youtubeEmbed(i.video_url):''}<div class="grid g2" style="margin-top:13px"><div class="card"><h3>Responsables</h3><div class="responsibles">${rp.map(pid=>`<button class="personLink" data-person-open="${pid}">${esc(displayName(pid))}</button>`).join('')||'<span class="tiny">Sin asignar</span>'}</div></div><div class="card"><h3>Estado en vivo</h3><div class="chips">${runChip(i.run_status||'pending')}</div></div></div><div class="card" style="margin-top:12px"><h3>Instrucciones</h3><p>${esc(i.description||'Sin descripción')}</p>${i.materials?`<h3 style="margin-top:14px">Materiales</h3><p>${esc(i.materials)}</p>`:''}${i.location?`<p><b>Lugar:</b> ${esc(i.location)}</p>`:''}</div>${canManageEvent(e.id)?`<div class="actions" style="margin-top:13px"><button class="btn" id="editItem">Editar</button><button class="btn danger" id="deleteItem">Eliminar</button></div>`:''}`);$$('[data-person-open]').forEach(b=>b.onclick=()=>personResponsibilitiesModal(b.dataset.personOpen));$('#editItem')?.addEventListener('click',()=>scheduleItemModal(i));$('#deleteItem')?.addEventListener('click',async()=>{if(!confirm('¿Eliminar esta actividad del cronograma?'))return;let {error}=await sb.from('tnt_schedule_items').delete().eq('id',i.id);if(error)return toast(errMsg(error));closeModal();await loadAll();render()})}
async function cycleRunStatus(id){let i=S.items.find(x=>x.id===id),next=i.run_status==='pending'?'live':i.run_status==='live'?'done':'pending';let {error}=await sb.from('tnt_schedule_items').update({run_status:next}).eq('id',id);if(error)return toast(errMsg(error));await loadAll();render()}

function eventMembersModal(eventId){let e=eventBy(eventId),current=eventMembers(eventId),map=new Map(current.map(m=>[m.person_id,m])),lockSelf=!isAdmin()&&!isPastor()&&current.some(m=>m.person_id===currentPersonId()&&m.event_role==='organizer');modal(`${sheetHead('Personas del evento','Organizador / Responsable / Participante y quién entra en los juegos')}<form class="form" id="membersForm"><div class="checkList">${S.people.filter(p=>p.active!==false).map(p=>{let m=map.get(p.id),locked=lockSelf&&p.id===currentPersonId();return `<div class="checkRow"><input type="checkbox" name="person" value="${p.id}" ${m||locked?'checked':''} ${locked?'disabled':''}><div style="flex:1"><b>${esc(displayName(p.id))}</b><div class="tiny">${esc(aByPid(p.id)?.ministry_role||'')}${locked?' · Tu permiso de organizador':''}</div></div><select name="role_${p.id}" ${locked?'disabled':''}>${['participant','responsible','organizer'].map(r=>`<option value="${r}" ${(locked?'organizer':m?.event_role)===r?'selected':''}>${r}</option>`).join('')}</select><label class="tiny"><input type="checkbox" name="games_${p.id}" ${m?.include_in_groups!==false?'checked':''}> juegos</label></div>`}).join('')}</div><button class="btn primary">Guardar personas</button></form>`,true);$('#membersForm').onsubmit=async ev=>{ev.preventDefault();let f=new FormData(ev.target),ids=f.getAll('person');if(lockSelf&&!ids.includes(currentPersonId()))ids.push(currentPersonId());let rows=ids.map(person_id=>({event_id:eventId,person_id,event_role:(lockSelf&&person_id===currentPersonId())?'organizer':(f.get('role_'+person_id)||'participant'),include_in_groups:f.get('games_'+person_id)==='on'}));if(rows.length){let r=await sb.from('tnt_event_members').upsert(rows,{onConflict:'event_id,person_id'});if(r.error)return toast(errMsg(r.error))}let remove=current.filter(m=>!ids.includes(m.person_id)).map(m=>m.person_id);if(remove.length){let d=await sb.from('tnt_event_members').delete().eq('event_id',eventId).in('person_id',remove);if(d.error)return toast(errMsg(d.error))}closeModal();await loadAll();render();toast('Personas actualizadas')}}



/* organizacion/org4a.js */
function groupConfigModal(dayId){let d=dayBy(dayId),e=eventBy(d?.event_id);if(!d||!e)return;let cfg=S.groupConfigs.find(c=>c.event_id===e.id&&c.day_id===d.id),existing=S.groups.filter(g=>g.event_id===e.id&&g.day_id===d.id).sort((a,b)=>a.sort_order-b.sort_order),count=cfg?.group_count||Math.max(2,existing.length||2),names=existing.length?existing.map(g=>g.name).join('\n'):['Rojo','Azul'].join('\n'),colors=existing.length?existing.map(g=>g.color).join('\n'):['#e5484d','#3b82f6'].join('\n');modal(`${sheetHead('Configurar grupos',d.label)}<form class="form" id="groupForm"><div class="field"><label>Cantidad de equipos</label><input type="number" name="count" min="2" max="8" value="${count}"></div><div class="formRow"><div class="field"><label>Nombres (uno por línea)</label><textarea name="names">${esc(names)}</textarea></div><div class="field"><label>Colores HEX (uno por línea)</label><textarea name="colors">${esc(colors)}</textarea></div></div><label class="checkRow"><input type="checkbox" name="age" ${cfg?.balance_age===false?'':'checked'}><span>Equilibrar edades</span></label><label class="checkRow"><input type="checkbox" name="sex" ${cfg?.balance_sex===false?'':'checked'}><span>Equilibrar sexo confirmado</span></label><label class="checkRow"><input type="checkbox" name="rotate" ${cfg?.avoid_previous_day===false?'':'checked'}><span>Evitar repetir equipo del día anterior</span></label><div class="warning">La app nunca infiere sexo por el nombre. Si falta sexo o fecha de nacimiento, te lo va a pedir antes de generar.</div><button class="btn primary">Generar equipos</button></form>`);$('#groupForm').onsubmit=e2=>generateGroups(e2,e,d,cfg)}
async function generateGroups(ev,e,d,cfg){ev.preventDefault();let f=new FormData(ev.target),count=Math.max(2,Math.min(8,Number(f.get('count'))||2)),names=String(f.get('names')||'').split(/\n+/).map(s=>s.trim()).filter(Boolean),colors=String(f.get('colors')||'').split(/\n+/).map(s=>s.trim()).filter(Boolean),balanceAge=f.get('age')==='on',balanceSex=f.get('sex')==='on',rotate=f.get('rotate')==='on';while(names.length<count)names.push(`Equipo ${names.length+1}`);while(colors.length<count)colors.push(['#e5484d','#3b82f6','#8b5cf6','#10b981','#f59e0b','#ec4899'][colors.length%6]);let pool=eventMembers(e.id).filter(m=>m.include_in_groups!==false).map(m=>pBy(m.person_id)).filter(Boolean);let missing=[];pool.forEach(p=>{if(balanceSex&&(!p.sex||p.sex==='U'))missing.push(displayName(p.id)+' (sexo)');if(balanceAge&&!p.birthday)missing.push(displayName(p.id)+' (nacimiento)')});if(missing.length)return toast('Faltan datos: '+missing.slice(0,4).join(', ')+(missing.length>4?'…':''));
  let payload={event_id:e.id,day_id:d.id,group_count:count,balance_age:balanceAge,balance_sex:balanceSex,avoid_previous_day:rotate,updated_by:currentPersonId()};let qr=cfg?await sb.from('tnt_group_configs').update(payload).eq('id',cfg.id):await sb.from('tnt_group_configs').insert(payload);if(qr.error)return toast(errMsg(qr.error));
  let old=S.groups.filter(g=>g.event_id===e.id&&g.day_id===d.id);if(old.length){let del=await sb.from('tnt_groups').delete().in('id',old.map(g=>g.id));if(del.error)return toast(errMsg(del.error))}
  let {data:newGroups,error:ge}=await sb.from('tnt_groups').insert([...Array(count)].map((_,i)=>({event_id:e.id,day_id:d.id,name:names[i],color:colors[i],sort_order:i}))).select();if(ge)return toast(errMsg(ge));newGroups.sort((a,b)=>a.sort_order-b.sort_order);
  let days=eventDays(e.id),idx=days.findIndex(x=>x.id===d.id),prev=idx>0?days[idx-1]:null,prevMap=new Map();if(prev){let pgs=S.groups.filter(g=>g.event_id===e.id&&g.day_id===prev.id);for(let g of pgs)for(let m of S.groupMembers.filter(x=>x.group_id===g.id))prevMap.set(m.person_id,g.name)}
  let persons=pool.map(p=>({p,age:age(p.birthday,d.date?new Date(d.date+'T12:00:00'):new Date()),sex:p.sex||'U'}));persons.sort((a,b)=>(a.sex||'').localeCompare(b.sex||'')||((b.age||0)-(a.age||0)));let teams=newGroups.map(g=>({g,people:[],ageSum:0,sex:{F:0,M:0,U:0}}));let targetAvg=persons.length?persons.reduce((s,x)=>s+(x.age||0),0)/persons.length:0;
  for(let x of persons){let scored=teams.map(t=>{let size=t.people.length,score=size*100;if(balanceSex)score+=(t.sex[x.sex]||0)*35;if(balanceAge&&x.age!=null){let avg=(t.ageSum+x.age)/(size+1);score+=Math.abs(avg-targetAvg)*4}if(rotate&&prevMap.get(x.p.id)===t.g.name)score+=75;return{t,score}}).sort((a,b)=>a.score-b.score);let t=scored[0].t;t.people.push(x);t.ageSum+=x.age||0;t.sex[x.sex]=(t.sex[x.sex]||0)+1}
  let rows=[];teams.forEach(t=>t.people.forEach(x=>rows.push({group_id:t.g.id,person_id:x.p.id,age_snapshot:x.age,sex_snapshot:x.sex})));if(rows.length){let ir=await sb.from('tnt_group_members').insert(rows);if(ir.error)return toast(errMsg(ir.error))}closeModal();await loadAll();render();toast('Equipos generados')}
async function moveGroupMember(personId,fromId,toId){if(fromId===toId)return;let old=S.groupMembers.find(m=>m.group_id===fromId&&m.person_id===personId);let d=await sb.from('tnt_group_members').delete().eq('group_id',fromId).eq('person_id',personId);if(d.error)return toast(errMsg(d.error));let i=await sb.from('tnt_group_members').insert({group_id:toId,person_id:personId,age_snapshot:old?.age_snapshot,sex_snapshot:old?.sex_snapshot});if(i.error)return toast(errMsg(i.error));await loadAll();render()}



